styleBlocks.css:
.report-builder-modal {
  display: flex;
  flex-direction: column;
  width: min(94vw, 840px);
  max-width: 840px !important;
  max-height: min(92vh, 860px);
  overflow: hidden;
  padding: 0;
}

.report-builder-body {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: 16px;
  min-height: 0;
  overflow: hidden;
}

.report-builder-scroll {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  padding-right: 2px;
  -webkit-overflow-scrolling: touch;
}

.report-builder-actions {
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  flex: 0 0 auto;
  margin-top: 0;
}

.report-builder-intro {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border));
  border-radius: 12px;
  background:
    radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--accent) 13%, transparent), transparent 46%),
    color-mix(in srgb, var(--bg-card) 82%, transparent);
}

.report-builder-local-badge,
.report-selection-count,
.report-optional-label {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border: 1px solid color-mix(in srgb, var(--border) 78%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-secondary) 78%, transparent);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.report-builder-local-badge {
  flex: 0 0 auto;
  min-height: 26px;
  padding: 4px 9px;
  color: var(--green);
}

.report-builder-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--bg-card) 72%, transparent);
}

.report-builder-section-head {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.report-builder-two-col {
  display: grid;
  grid-template-columns: minmax(180px, 0.8fr) minmax(260px, 1.2fr);
  align-items: start;
}

.report-builder-label {
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.report-builder-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.report-builder-field-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.report-selection-count {
  min-height: 22px;
  padding: 2px 7px;
  font-family: var(--font-sans);
  letter-spacing: 0;
  text-transform: none;
}

.report-builder-select {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
}

.report-preset-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.report-preset-btn,
.report-mini-btn {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, color 0.15s;
}

.report-preset-btn {
  display: flex;
  min-height: 70px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 4px;
  padding: 10px 12px;
  text-align: left;
}

.report-section-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.report-builder-check,
.report-category-row {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  min-height: 44px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 13px;
}

.report-builder-check:has(input:checked),
.report-category-row:has(input:checked) {
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border));
  background: color-mix(in srgb, var(--accent) 7%, var(--bg-secondary));
}

.report-builder-row-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.report-category-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.report-category-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.report-category-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.report-category-title {
  overflow: hidden;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.report-ai-builder {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  padding: 12px;
}

.report-ai-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
}

.report-ai-summary-text {
  width: 100%;
  height: min(28vh, 220px);
  min-height: 96px;
  max-height: 320px;
  margin-top: 10px;
  padding: 10px 11px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  line-height: 1.45;
  overflow-y: auto;
  overscroll-behavior: contain;
  resize: vertical;
  -webkit-overflow-scrolling: touch;
}

.report-builder-preview-btn {
  min-width: 132px;
  color: #07111f;
  box-shadow: 0 10px 28px color-mix(in srgb, var(--accent) 24%, transparent);
}

#tour-spotlight {
  position: fixed; z-index: 501; border-radius: 8px;
  box-shadow: 0 0 0 9999px rgba(0,0,0,0.65);
  transition: all 0.3s ease; pointer-events: none;
}

#tour-tooltip {
  position: fixed; z-index: 502; background: var(--bg-secondary);
  border: 1px solid var(--border); border-radius: var(--radius);
  padding: 20px; max-width: 340px; width: max-content;
  box-shadow: var(--shadow-lg);
}
